const hits = $input.first().json.result;

return [{
  json: {
    ids: hits.map(h => h.payload.product_id),
    scores: hits.map(h => h.score)
  }
}];

const products = $input.all().map(i => i.json);
const src = $('Extract ids').first().json;

const byId = Object.fromEntries(products.map(p => [p.id, p]));

const ranked = src.ids
  .map((id, i) => ({ ...byId[id], score: src.scores[i] }))
  .filter(p => p.id);

return [{ json: { products: ranked, query: $('Query').first().json.query } }]

const { products, query } = $input.first().json;

const catalog = products.map((p, i) =>
  `${i + 1}. ${p.name} (id: ${p.id}, price: ${p.price})\n${p.rich_description}`
).join('\n\n');

const system = `You are a shopping assistant for an online clothing store.

Rules:
- Recommend ONLY from the products listed in the user message.
- Never invent products, prices, materials or details that are not listed.
- If nothing fits the request, return an empty products array and explain honestly.
- Pick the 2-3 best matches.
- Be warm and concise. No sales hype.

LANGUAGE: Write "reply" and every "reason" in the SAME language as the customer request. If the request is in English, answer in English. If in Ukrainian, answer in Ukrainian. Never switch to another language.

Respond ONLY with valid JSON, no markdown, in this exact shape:
{
  "reply": "your message to the customer",
  "products": [
    { "id": 3, "reason": "one short sentence why it fits" }
  ]
}`;

const user = `Customer request: ${query}

Available products:
${catalog}`;

return [{ json: { system, user } }];

const raw = $input.first().json.choices[0].message.content;
const parsed = JSON.parse(raw);

const catalog = $('Build context').first().json.products;
const byId = Object.fromEntries(catalog.map(p => [p.id, p]));

const products = (parsed.products || [])
  .filter(p => byId[p.id])
  .map(p => ({
    id: p.id,
    reason: p.reason,
    name: byId[p.id].name,
    price: byId[p.id].price,
    image_url: byId[p.id].image_url
  }));

return [{ json: { reply: parsed.reply, products } }];

const body = $input.first().json.body || {};

const query = String(body.query || '').trim();

// рядком, а не масивом: Search Qdrant вставляє це прямо в JSON-тіло
const genders = body.gender === 'womens' ? '["womens","unisex"]'
              : body.gender === 'mens'   ? '["mens","unisex"]'
              : '["mens","womens","unisex"]';

// історія приходить з фронтенду; поки її немає — працюємо без пам'яті
const history = Array.isArray(body.history) ? body.history.slice(-6) : [];
const historyText = history.length
  ? history.map(m => `${m.role === 'user' ? 'Customer' : 'Assistant'}: ${m.text}`).join('\n')
  : '(no previous messages)';

// Єдине джерело правди про політику магазину. Редагуй під себе.
const STORE_FACTS = `- We ship to Greece, Ukraine, Cyprus, Germany and Poland. Nowhere else.
- Shipping is free on every order. Delivery takes 3-7 business days.
- Payment is by card only (Visa, Mastercard, Amex), handled by Stripe. No cash on delivery.
- Returns accepted within 14 days, unworn and with tags. The customer pays return postage.
- Sizes available for an item are shown on its product page. If you are between sizes, size up.
- After payment you get a receipt by email. The store confirms the order and ships it.`;

const route_system = `You are the router for an online clothing store assistant.

Reply ONLY with valid JSON, no markdown, with the keys in exactly this order:
{ "intent": "product" | "other", "language": "...", "search_query": "...", "reply": "..." }

STEP 1 — "language": name the language of the NEW customer message ("English", "Ukrainian", "Russian", "Greek", ...). Judge only by that message, never by the history and never by the language of these instructions.

STEP 2 — "intent":
"product" — the customer is looking for clothing, or asking about style, fit, colour, occasion, or following up on items just shown.
"other" — everything else: shipping, returns, payment, sizing policy, order status, greetings, small talk, or anything this store cannot answer.

STEP 3 — the remaining fields.

If intent is "product":
- "search_query" is a STANDALONE search phrase in ENGLISH that makes sense without the conversation. Resolve every pronoun and reference from the history. "do you have it in blue" after a linen shirt becomes "blue linen shirt".
- "reply" is an empty string.

If intent is "other":
- "search_query" is an empty string.
- "reply" answers using ONLY the store facts below. If the facts do not cover the question, say honestly that you can only help with the catalogue, shipping, returns and payment.
- "reply" MUST be written in the language you named in the "language" field. This overrides everything else.

Store facts:
${STORE_FACTS}`;

const route_user = `Conversation so far:
${historyText}

New customer message: ${query}`;

return [{ json: { query, genders, route_system, route_user } }];

const raw = $input.first().json.choices[0].message.content;
const parsed = JSON.parse(raw);

const intent = parsed.intent === 'other' ? 'other' : 'product';
const rewritten = String(parsed.search_query || '').trim();

return [{ json: {
  intent,
  // якщо модель повернула порожній rewrite — падаємо назад на оригінал, а не в порожнечу
  query: intent === 'product' ? (rewritten || $('Query').first().json.query) : '',
  reply: String(parsed.reply || '')
}}];
